import { useContext, useEffect, useState } from 'react';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import { useNavigate, useParams } from 'react-router-dom';
import axios from 'axios';
import './messages.scss';

const Messages = () => {
  const { currentUser } = useContext(AuthContext);
  const { darkMode } = useContext(DarkModeContext);
  const navigate = useNavigate();
  const { id } = useParams();
  const [friends, setFriends] = useState([]);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!currentUser) {
      navigate('/login');
      return;
    }

    const fetchFriends = async () => {
      const token = sessionStorage.getItem('token');
      if (!token) {
        setError('Please log in to view messages.');
        setLoading(false);
        return;
      }

      try {
        console.log(`Messages: Fetching friends for user ID: ${currentUser._id}`);
        const res = await axios.get(`http://localhost:5000/api/users/${currentUser._id}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        console.log('Messages: Fetched friends=', res.data.friends);
        res.data.friends.forEach(friend => {
          console.log(`Messages: Friend ${friend.name} profilePicture=`, friend.profilePicture);
        });
        setFriends(res.data.friends || []);
        setError(null);
      } catch (err) {
        console.error('Messages: Error fetching friends:', err.message);
        console.error('Messages: Response:', err.response?.data);
        setError(err.response?.data?.message || 'Failed to load friends.');
        setFriends([]);
      } finally {
        setLoading(false);
      }
    };

    fetchFriends();
  }, [currentUser, navigate]);

  useEffect(() => {
    if (!id) return;

    const fetchMessages = async () => {
      const token = sessionStorage.getItem('token');
      if (!token) {
        setError('Please log in to view messages.');
        return;
      }

      try {
        console.log(`Messages: Fetching messages for friend ID: ${id}`);
        const res = await axios.get(`http://localhost:5000/api/messages/${id}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        console.log('Messages: Fetched messages=', res.data);
        setMessages(res.data || []);
        setError(null);
      } catch (err) {
        console.error('Messages: Error fetching messages:', err.message);
        console.error('Messages: Response:', err.response?.data);
        setError(err.response?.data?.message || 'Failed to load messages.');
        setMessages([]);
      }
    };

    fetchMessages();
  }, [id]);

  const handleSendMessage = async () => {
    if (!newMessage.trim()) return;

    const token = sessionStorage.getItem('token');
    if (!token) {
      setError('Please log in to send messages.');
      return;
    }

    try {
      console.log(`Messages: Sending message to friend ID: ${id}`);
      const res = await axios.post(
        'http://localhost:5000/api/messages',
        {
          recipientId: id,
          content: newMessage,
        },
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      console.log('Messages: Message sent=', res.data);
      setMessages([...messages, res.data]);
      setNewMessage('');
    } catch (err) {
      console.error('Messages: Error sending message:', err.message);
      console.error('Messages: Response:', err.response?.data);
      setError(err.response?.data?.message || 'Failed to send message.');
    }
  };

  const getProfilePictureUrl = (profilePicture) => {
    if (!profilePicture) {
      console.log('Messages: No profile picture provided, using fallback');
      return 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
    }
    if (profilePicture.startsWith('http')) {
      console.log('Messages: Using external profile picture URL:', profilePicture);
      return profilePicture;
    }
    const normalizedPath = profilePicture.replace(/^\/Uploads\//i, '/Uploads/');
    const url = `http://localhost:5000${normalizedPath}?t=${new Date().getTime()}`;
    console.log('Messages: Profile picture URL:', url);
    return url;
  };

  if (!currentUser) {
    return <div className={`messages ${darkMode ? 'theme-dark' : 'theme-light'}`}>Please log in to view messages.</div>;
  }

  if (loading) {
    return <div className={`messages ${darkMode ? 'theme-dark' : 'theme-light'}`}>Loading...</div>;
  }

  if (error) {
    return <div className={`messages ${darkMode ? 'theme-dark' : 'theme-light'} error`}>{error}</div>;
  }

  return (
    <div className={`messages ${darkMode ? 'theme-dark' : 'theme-light'}`}>
      <div className="sidebar">
        <h3>Chats</h3>
        {friends.length > 0 ? (
          friends.map((friend) => (
            <div
              key={friend._id}
              className={`friend ${id === friend._id ? 'active' : ''}`}
              onClick={() => navigate(`/messages/${friend._id}`)}
            >
              <img
                src={getProfilePictureUrl(friend.profilePicture)}
                alt={`${friend.name}'s profile`}
                className="avatar"
                onError={(e) => {
                  console.error(`Messages: Image load error for ${friend.name}:`, e);
                  e.target.src = 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
                }}
              />
              <span>{friend.name}</span>
            </div>
          ))
        ) : (
          <p>No friends yet.</p>
        )}
      </div>
      <div className="chat">
        {id ? (
          <>
            <div className="messages-list">
              {messages.map((msg) => (
                <div
                  key={msg._id}
                  className={`message ${msg.senderId === currentUser._id ? 'sent' : 'received'}`}
                >
                  <p>{msg.content}</p>
                  <span>{new Date(msg.createdAt).toLocaleTimeString()}</span>
                </div>
              ))}
            </div>
            <div className="message-input">
              <input
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                placeholder="Type a message..."
              />
              <button onClick={handleSendMessage}>Send</button>
            </div>
          </>
        ) : (
          <p>Select a friend to start chatting.</p>
        )}
      </div>
    </div>
  );
};

export default Messages;
